CREATE TABLE Blog (
    id INT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    title VARCHAR(20) NOT NULL,
    content VARCHAR(250),
    img BYTEA
);
CREATE TABLE BlogImage (
    id_image INT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    id_blog INT NOT NULL,
    image BYTEA NOT NULL,
    
   
    CONSTRAINT fk_blog 
        FOREIGN KEY (id_blog) 
        REFERENCES Blog(id) 
        ON DELETE CASCADE
);



